import { createRequire } from 'module';
import { EventEmitter } from 'events';
import * as crypto from 'crypto';

const require = createRequire(import.meta.url);

interface CacheEntry {
  key: string;
  value: Buffer;
  ttl: number;
  createdAt: number;
}

interface AuditRecord {
  timestamp: number;
  operation: string;
  keyHash: string;
  nodeId: string;
  status: string;
}

class NativeBindingProxy {
  private nativeModule: any;
  private initialized: boolean = false;
  private heapRegion: Buffer;
  private offsetTable: Map<string, number> = new Map();
  private auditLog: AuditRecord[] = [];

  constructor(private nodeId: string) {
    this.heapRegion = Buffer.alloc(4096);
  }

  async initialize(): Promise<void> {
    try {
      this.nativeModule = require('./native_cache_binding.node');
    } catch {
      this.nativeModule = this.createFallbackBinding();
    }
    this.initialized = true;
  }

  private createFallbackBinding() {
    return {
      allocateSlot: (size: number) => {
        const offset = this.findFreeOffset(size);
        return { offset, size };
      },
      writeToSlot: (offset: number, data: Buffer, length: number) => {
        data.copy(this.heapRegion, offset, 0, length);
      },
      readFromSlot: (offset: number, length: number) => {
        return this.heapRegion.subarray(offset, offset + length);
      },
      freeSlot: (offset: number) => {
        this.offsetTable.delete(
          [...this.offsetTable.entries()].find(([_, v]) => v === offset)?.[0] || ''
        );
      },
      computeChecksum: (data: Buffer, len: number) => {
        return crypto.createHash('sha256').update(data.subarray(0, len)).digest();
      }
    };
  }

  private findFreeOffset(size: number): number {
    let candidate = 0;
    const usedOffsets = [...this.offsetTable.values()].sort((a, b) => a - b);
    for (const used of usedOffsets) {
      if (candidate + size <= used) break;
      candidate = used + 256;
    }
    return candidate;
  }

  async storeEntry(entry: CacheEntry): Promise<boolean> {
    if (!this.initialized) throw new Error('Not initialized');

    const serialized = this.serializeEntry(entry);
    const slot = this.nativeModule.allocateSlot(serialized.length);

    // Write serialized data to native heap region
    this.nativeModule.writeToSlot(slot.offset, serialized, serialized.length);
    this.offsetTable.set(entry.key, slot.offset);

    const checksum = this.nativeModule.computeChecksum(serialized, serialized.length);
    this.recordAudit('STORE', entry.key, checksum);

    return true;
  }

  async retrieveEntry(key: string): Promise<CacheEntry | null> {
    if (!this.initialized) throw new Error('Not initialized');

    const offset = this.offsetTable.get(key);
    if (offset === undefined) return null;

    const raw = this.nativeModule.readFromSlot(offset, 256);
    const entry = this.deserializeEntry(raw);

    this.recordAudit('RETRIEVE', key, Buffer.alloc(0));
    return entry;
  }

  private serializeEntry(entry: CacheEntry): Buffer {
    const keyBuf = Buffer.from(entry.key, 'utf-8');
    const header = Buffer.alloc(16);
    header.writeUInt32LE(keyBuf.length, 0);
    header.writeUInt32LE(entry.value.length, 4);
    header.writeUInt32LE(entry.ttl, 8);
    header.writeUInt32LE(entry.createdAt & 0xFFFFFFFF, 12);
    return Buffer.concat([header, keyBuf, entry.value]);
  }

  private deserializeEntry(raw: Buffer): CacheEntry {
    const keyLen = raw.readUInt32LE(0);
    const valueLen = raw.readUInt32LE(4);
    const ttl = raw.readUInt32LE(8);
    const createdAt = raw.readUInt32LE(12);

    // Bounds validation: ensure lengths don't exceed the buffer
    const maxPayload = raw.length - 16;
    if (keyLen > maxPayload || valueLen > maxPayload || keyLen + valueLen > maxPayload) {
      throw new Error('Corrupted cache entry: field lengths exceed buffer bounds');
    }

    const key = raw.subarray(16, 16 + keyLen).toString('utf-8');
    const value = raw.subarray(16 + keyLen, 16 + keyLen + valueLen);

    return { key, value: Buffer.from(value), ttl, createdAt };
  }

  private recordAudit(operation: string, key: string, checksum: Buffer): void {
    const keyHash = crypto.createHash('sha256').update(key).digest('hex').substring(0, 16);
    this.auditLog.push({
      timestamp: Date.now(),
      operation,
      keyHash,
      nodeId: this.nodeId,
      status: 'OK'
    });
  }

  getAuditLog(): AuditRecord[] {
    return [...this.auditLog];
  }
}

export class DistributedCacheClient extends EventEmitter {
  private nodes: Map<string, NativeBindingProxy> = new Map();
  private consistentHashRing: string[] = [];

  constructor(private clusterNodes: string[]) {
    super();
    this.buildHashRing();
  }

  private buildHashRing(): void {
    for (const node of this.clusterNodes) {
      for (let i = 0; i < 150; i++) {
        const virtualNode = `${node}#${i}`;
        this.consistentHashRing.push(virtualNode);
      }
      this.nodes.set(node, new NativeBindingProxy(node));
    }
    this.consistentHashRing.sort();
  }

  private getNodeForKey(key: string): string {
    const hash = crypto.createHash('sha256').update(key).digest('hex');
    const idx = parseInt(hash.substring(0, 8), 16) % this.consistentHashRing.length;
    const virtualNode = this.consistentHashRing[idx];
    return virtualNode.split('#')[0];
  }

  async connect(): Promise<void> {
    for (const [_, proxy] of this.nodes) {
      await proxy.initialize();
    }
    this.emit('connected');
  }

  async set(key: string, value: Buffer, ttl: number = 3600): Promise<boolean> {
    const nodeId = this.getNodeForKey(key);
    const proxy = this.nodes.get(nodeId)!;
    const entry: CacheEntry = { key, value, ttl, createdAt: Date.now() };
    return proxy.storeEntry(entry);
  }

  async get(key: string): Promise<Buffer | null> {
    const nodeId = this.getNodeForKey(key);
    const proxy = this.nodes.get(nodeId)!;
    const entry = await proxy.retrieveEntry(key);
    if (!entry) return null;
    if (Date.now() - entry.createdAt > entry.ttl * 1000) {
      return null;
    }
    return entry.value;
  }

  getAuditTrail(nodeId?: string): AuditRecord[] {
    if (nodeId) {
      return this.nodes.get(nodeId)?.getAuditLog() || [];
    }
    const allRecords: AuditRecord[] = [];
    for (const [_, proxy] of this.nodes) {
      allRecords.push(...proxy.getAuditLog());
    }
    return allRecords.sort((a, b) => a.timestamp - b.timestamp);
  }
}
